"""説得・マーケティング・論説構造の純粋骨格 20 パターン（persuasion_marketing シード）の著作スクリプト。

手書き設計したパターン定義（コンパクトな dict 群）から ``UniversalStructure`` を組み立て、
品質基準をすべて検証してから ``persuasion_and_marketing_structures.json`` を再生成する。

再生成コマンド::

    python -m core.structure_engine.seeds.authoring.build_persuasion_marketing

情報チャネルの解釈（本カテゴリ共通）:
- ``audience_knowledge``: 読者・顧客が理解し納得している情報量
- ``character_knowledge``: 語り手・ブランド側（事例型では事例の当事者）が把握・開示・示唆している情報量
- 情報非対称性 A = audience − character が負: 語り手が先行する「好奇心ギャップ」（伏せた答え・反論の先回り）
- A が正: 読者が語りの先を読む「先回り」（自己発見による自己説得・結果先出しによる劇的アイロニー）

波形は各チャネル 6〜12 個のキーフレームを PCHIP 単調補間して 21 点（20 分割）に展開する。
キーフレームの t は 0.05 刻みに置き、転換点ビートの t を緊張度の極値（または読者認知量の跳躍）と一致させる。
"""

