PATTERN_DEFINITIONS: list[dict[str, Any]] = []


def _n(nid: str, kind: str, role: str, label: str, desc: str, weight: float, slot: str) -> dict[str, Any]:
    """力学グラフのノード定義。"""
    return {"id": nid, "kind": kind, "role": role, "label": label, "description": desc, "weight": weight, "slot": slot}


def _e(src: str, dst: str, kind: str, intensity: float, label: str, at: float, gradient: float = 0.0) -> dict[str, Any]:
    """力学グラフの有向エッジ定義（at は顕在化する正規化時刻）。"""
    return {
        "source": src,
        "target": dst,
        "kind": kind,
        "intensity": intensity,
        "gradient": gradient,
        "label": label,
        "activation_t": at,
    }


def _b(
    bid: str,
    btype: str,
    t: float,
    label: str,
    function: str,
    causes: list[str],
    dt: float,
    di: float,
    nodes: list[str],
    tp: bool = False,
) -> dict[str, Any]:
    """構造ビート定義（dt=緊張度変化、di=情報非対称性変化、tp=転換点）。"""
    return {
        "id": bid,
        "beat_type": btype,
        "t": t,
        "span": 0.05,
        "label": label,
        "function": function,
        "causes": list(causes),
        "tension_delta": dt,
        "information_shift": di,
        "involved_nodes": list(nodes),
        "is_turning_point": tp,
    }


def _m(
    mid: str,
    category: str,
    name: str,
    desc: str,
    trigger: str,
    effect: str,
    theory: str,
    strength: float,
    beats: list[str],
    nodes: list[str],
) -> dict[str, Any]:
    """認知・共感メカニズム定義。"""
    return {
        "id": mid,
        "category": category,
        "name": name,
        "description": desc,
        "trigger": trigger,
        "effect": effect,
        "theory": theory,
        "strength": strength,
        "linked_beats": list(beats),
        "linked_nodes": list(nodes),
    }


def _s(
    name: str,
    category: str,
    desc: str,
    constraints: list[str],
    manga: str,
    marketing: str,
    article: str,
) -> dict[str, Any]:
    """ブループリントのスロット定義（examples は3領域の充填例）。"""
    return {
        "name": name,
        "description": desc,
        "category": category,
        "constraints": list(constraints),
        "examples": {"manga": manga, "marketing": marketing, "article": article},
        "required": True,
    }


