# 組立・検証・出力
# ---------------------------------------------------------------------------


def build_structure(definition: dict[str, Any]) -> UniversalStructure:
    """1パターン定義から UniversalStructure を組み立てて検証する。"""
    wave = EmotionalInformationWave.from_keyframes(definition["wave"], n=WAVE_MIN_POINTS)
    payload = {
        "id": definition["id"],
        "metadata": {
            "title": definition["title"],
            "summary": definition["summary"],
            "category": CATEGORY,
            "source_kind": "seed",
            "tags": definition["tags"],
            "origin_domain": definition["origin_domain"],
            "lineage": definition["lineage"],
            "parent_ids": [],
            "language": "ja",
            "version": 1,
            "created_at": SEED_CREATED_AT,
            "notes": definition.get("notes", DEFAULT_NOTES),
        },
        "tension_graph": {"nodes": definition["nodes"], "edges": definition["edges"]},
        "wave": wave.model_dump(mode="json"),
        "beats": {"beats": definition["beats"]},
        "mechanics": {
            "mechanisms": definition["mechanisms"],
            "empathy_anchor": definition["empathy_anchor"],
            "immersion_drivers": definition["immersion_drivers"],
            "emotion_sequence": definition["emotion_sequence"],
        },
        "blueprint": {
            "template": definition["template"],
            "slots": definition["slots"],
            "invariants": definition["invariants"],
        },
        "transfer_guide": definition["transfer"],
        "rhythm_profile": None,
    }
    return UniversalStructure.model_validate(payload)


def build_all() -> list[UniversalStructure]:
    """全パターンを組み立てる。"""
    return [build_structure(definition) for definition in PATTERN_DEFINITIONS]


def _local_extrema(values: np.ndarray) -> set[int]:
    """21点配列の局所極値インデックス（端点を含む）。"""
    extrema = {0, len(values) - 1}
    for i in range(1, len(values) - 1):
        left, mid, right = values[i - 1], values[i], values[i + 1]
        if (mid >= left and mid >= right and (mid > left or mid > right)) or (
            mid <= left and mid <= right and (mid < left or mid < right)
        ):
            extrema.add(i)
    return extrema


def _check_range(errors: list[str], sid: str, label: str, value: int, low: int, high: int) -> None:
    if not low <= value <= high:
        errors.append(f"{sid}: {label} が {value}（基準 {low}〜{high}）")


def validate_patterns(structures: list[UniversalStructure]) -> dict[str, Any]:
    """SPEC §10 の品質基準・ID規則・波形固有性（緊張度の相関 < 0.97）を検証する。"""
    errors: list[str] = []
    if len(structures) != 20:
        errors.append(f"パターン数が {len(structures)} 件（20件必須）")
    ids = [s.id for s in structures]
    if len(set(ids)) != len(ids):
        errors.append("IDが重複しています")
    all_edge_kinds: set[str] = set()
    for index, (structure, definition) in enumerate(zip(structures, PATTERN_DEFINITIONS), start=1):
        sid = structure.id
        match = re.fullmatch(r"pm_(\d{2})_[a-z0-9_]+", sid)
        if match is None or int(match.group(1)) != index:
            errors.append(f"{sid}: ID規則 pm_{index:02d}_<slug> に一致しません")
        graph = structure.tension_graph
        _check_range(errors, sid, "ノード数", len(graph.nodes), 4, 8)
        _check_range(errors, sid, "エッジ数", len(graph.edges), 5, 12)
        _check_range(errors, sid, "ビート数", len(structure.beats.beats), 6, 10)
        _check_range(errors, sid, "メカニズム数", len(structure.mechanics.mechanisms), 3, 5)
        _check_range(errors, sid, "スロット数", len(structure.blueprint.slots), 6, 10)
        _check_range(errors, sid, "不変条件数", len(structure.blueprint.invariants), 3, 6)
        _check_range(errors, sid, "タグ数", len(structure.metadata.tags), 3, 6)
        _check_range(errors, sid, "転換点数", len(structure.beats.turning_points()), 2, 10)
        if any(node.slot is None for node in graph.nodes):
            errors.append(f"{sid}: スロット未割当のノードがあります")
        kinds = {edge.kind.value for edge in graph.edges}
        all_edge_kinds |= kinds
        if len(kinds) < 4:
            errors.append(f"{sid}: エッジ種別が {len(kinds)} 種（4種以上必須）")
        for edge in graph.edges:
            if edge.kind in (EdgeKind.POWER_GRADIENT, EdgeKind.ASYMMETRY) and edge.gradient == 0.0:
                errors.append(f"{sid}: 勾配系エッジ {edge.source}->{edge.target} の gradient が 0")
        guide = structure.transfer_guide
        if not (guide.manga and guide.marketing and guide.article):
            errors.append(f"{sid}: 転用ガイドが3領域そろっていません")
        for channel in WAVE_CHANNELS:
            count = len(definition["wave"][channel])
            if not 6 <= count <= 12:
                errors.append(f"{sid}: {channel} のキーフレーム数が {count}（6〜12）")
        for beat in structure.beats.beats[1:]:
            if not beat.causes:
                errors.append(f"{sid}: ビート {beat.id} に因果（causes）がありません")
        tension = structure.wave.channel("tension")
        audience = structure.wave.channel("audience_knowledge")
        extrema = _local_extrema(tension)
        last = len(tension) - 1
        for beat in structure.beats.turning_points():
            i = int(round(beat.t * last))
            window = {j for j in (i - 1, i, i + 1) if 0 <= j <= last}
            jump = any(abs(audience[j] - audience[j - 1]) >= 0.08 for j in window if j >= 1)
            if not (window & extrema) and not jump:
                errors.append(f"{sid}: 転換点 {beat.id}（t={beat.t}）が緊張度の極値・認知量の跳躍と一致しません")
        for issue in audit_structure(structure):
            errors.append(f"{sid}: 整合性監査 {issue.code}（{issue.location}）: {issue.message}")
        corpus = " ".join(structure.text_fields() + list(structure.metadata.lineage))
        if re.search(r"https?://|www\.", corpus):
            errors.append(f"{sid}: URL様の文字列を含みます")
    missing_kinds = {kind.value for kind in EdgeKind} - all_edge_kinds
    if missing_kinds:
        errors.append(f"カテゴリ全体で未使用のエッジ種別: {sorted(missing_kinds)}")
    tensions = np.vstack([s.wave.channel("tension") for s in structures]) if structures else np.zeros((0, 0))
    max_corr = -1.0
    max_pair: tuple[str, str] = ("", "")
    for a, b in combinations(range(len(structures)), 2):
        corr = float(np.corrcoef(tensions[a], tensions[b])[0, 1])
        if corr > max_corr:
            max_corr, max_pair = corr, (structures[a].id, structures[b].id)
        if corr >= 0.97:
            errors.append(f"緊張度波形の相関が高すぎます: {structures[a].id} × {structures[b].id} = {corr:.3f}")
    return {
        "count": len(structures),
        "errors": errors,
        "max_tension_correlation": round(max_corr, 4),
        "max_correlation_pair": max_pair,
        "edge_kinds_used": sorted(all_edge_kinds),
    }


def main() -> None:
    """全パターンを検証して JSON を書き出す。"""
    structures = build_all()
    report = validate_patterns(structures)
    if report["errors"]:
        for error in report["errors"]:
            print(f"[ERROR] {error}", file=sys.stderr)
        raise SystemExit(1)
    document = {
        "schema_version": SCHEMA_VERSION,
        "category": CATEGORY,
        "description": FILE_DESCRIPTION,
        "patterns": [structure.model_dump(mode="json") for structure in structures],
    }
    OUTPUT_PATH.write_text(json.dumps(document, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"{len(structures)} パターンを書き出しました: {OUTPUT_PATH}")
    print(f"緊張度波形の最大相関: {report['max_tension_correlation']} {report['max_correlation_pair']}")
    for structure in structures:
        print(f"  {structure.id}: {structure.metadata.title}")


if __name__ == "__main__":
    main()
